import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.nextLine();
        int flag = 0;
        String processed = inputStr.replace("at", "@").replace("dot", ".");
        char[] charArray = processed.toCharArray();
        int length = charArray.length;

        if (length > 0) {
            if (charArray[0] == '.') {
                charArray[0] = 'd'; // placeholder for 'dot'
            }
            if (charArray[length - 1] == '.') {
                charArray[length - 1] = 'd'; // placeholder for 'dot'
            }
            if (charArray[0] == '@') {
                charArray[0] = 'a'; // placeholder for 'at'
            }
            if (charArray[length - 1] == '@') {
                charArray[length - 1] = 'a'; // placeholder for 'at'
            }
        }

        for (int i = 0; i < length; i++) {
            if (charArray[i] == '@' && flag == 0) {
                flag = 1;
            } else if (charArray[i] == '@') {
                charArray[i] = 'a'; // placeholder for 'at'
            }
            System.out.print(charArray[i]);
        }
        scanner.close();
    }
}
